INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(18401, 'Jeremiah 23:30', 'Jeremiah', 23, 30, '&nbsp;نو ځکه زۀ د هغه پېغمبرانو خِلاف يم څوک چې د يو بل نه خبرې نقل کوى او بيا خلقو ته وائى چې دا کلام زما د طرفه دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18402, 'Jeremiah 23:31', 'Jeremiah', 23, 31, '&nbsp;مالِک خُدائ فرمائى چې، ”زۀ د هغه پېغمبرانو خِلاف هم يم چا چې خپله خولۀ پرانستى وى او د خپل ځان نه لګيا وى خبرې کوى او بيا وائى چې مالِک خُدائ داسې فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18403, 'Jeremiah 23:32', 'Jeremiah', 23, 32, '&nbsp;په حقيقت کښې زۀ د هغوئ خلاف يم،“ مالِک خُدائ دا بيان کوى، ”څوک چې د دروغو خوبونه جوړوى او زما خلقو ته هغه بيانوى، او هغوئ په خپلو بې‌حسابه دروغو سره زما خلق بې‌لارې کوى، حال دا چې نۀ ما هغوئ لېږلى دى او نۀ مې مقرر کړى دى. او هغوئ د خلقو د فائدې هيڅ خبرې نۀ کوى.“ مالِک خُدائ دا بيان کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18404, 'Jeremiah 23:33', 'Jeremiah', 23, 33, '&nbsp;”يرمياه، کله چې د دې خلقو نه عام کس يا پېغمبر يا اِمام ستا نه تپوس وکړى چې، تا سره د مالِک خُدائ نه کوم دروند پيټے شته څۀ؟ نو تۀ په جواب کښې ورته ووايه، نو هغه دروند پيټے هم تۀ يې، مالِک خُدائ فرمائى، زۀ به تا وغورزوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18405, 'Jeremiah 23:34', 'Jeremiah', 23, 34, '&nbsp;کۀ چرې يو پېغمبر، يا اِمام يا بل څوک دا دعوىٰ وکړى چې، ”دا د مالِک خُدائ دروند پيټے دے،“ زۀ به دۀ له او د دۀ خاندان له سزا ورکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18406, 'Jeremiah 23:35', 'Jeremiah', 23, 35, '&nbsp;نو بيا دې دا هر يو کس په تاسو کښې د يو بل نه او د خپلو دوستانو او خپلوانو نه تپوس کوى چې، ”مالِک خُدائ په جواب کښې څۀ فرمائيلى دى؟“ او يا دا چې، ”مالِک خُدائ کومه خبره کړې ده؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18407, 'Jeremiah 23:36', 'Jeremiah', 23, 36, '&nbsp;خو نور به تۀ بيا کله هم دا ونۀ وائې چې، ”د مالِک خُدائ پېغام يو دروند پيټے دے،“ ځکه چې د هر سړى خپله خبره د هغۀ پېغام وګرځېدو نو تاسو بيا دغه شان د ژوندى مالِک خُدائ، ربُ الافواج خُدائ زمونږ د خُدائ پاک پېغام ته تعبير ورکوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18408, 'Jeremiah 23:37', 'Jeremiah', 23, 37, '&nbsp;تاسو پېغمبرانو ته داسې ووايئ چې، ”مالِک خُدائ تاسو له څۀ جواب درکړو؟ مالِک خُدائ څۀ فرمائيلى دى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18409, 'Jeremiah 23:38', 'Jeremiah', 23, 38, '&nbsp;او کۀ بيا هم تاسو دا دعوىٰ کوئ چې، ”دا د مالِک خُدائ نه دروند پيټے دے،“ نو مالِک خُدائ بيا داسې فرمائى چې، ”تاسو خبرې خو کوئ چې دا د مالِک خُدائ نه دروند پيټے دے، اګر چې ما درته فرمائيلى وُو چې داسې خبرې مۀ کوئ چې دا د مالِک خُدائ د طرف نه دروند پيټے دے،“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18410, 'Jeremiah 23:39', 'Jeremiah', 23, 39, '&nbsp;‎‏نو په دې وجه به زۀ تاسو په يقين سره هېر کړم او سره د هغه ښاره کوم چې ما تاسو او ستاسو پلار نيکۀ له ورکړو د خپل حضور نه لرې وشړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18411, 'Jeremiah 23:40', 'Jeremiah', 23, 40, '&nbsp;زۀ به په تاسو باندې نۀ ختمېدونکے لعنت او ابدى شرم نازل کړم چې هيڅکله به هېرولے نۀ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18412, 'Jeremiah 24:1', 'Jeremiah', 24, 1, '&nbsp;وروستو د دې نه چې د بابل بادشاه نبوکدنضر د يهوياکين د يهويقيم زوئ د يهوداه بادشاه بابل ته سره د آفسرانو، کاريګرانو او لوهارانو قېديان بوتلل نو بيا مالِک خُدائ ما ته په رويا کښې د اينځرو دوه ټوکرۍ راوښودلې چې د مالِک خُدائ د کور مخې ته پرتې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18413, 'Jeremiah 24:2', 'Jeremiah', 24, 2, '&nbsp;په يوه ټوکرۍ کښې اول موسمى او پاخۀ اينځر وُو، او په بله ټوکرۍ کښې خراب اينځر وُو، دومره ډېر خراب چې د خوړلو نۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18414, 'Jeremiah 24:3', 'Jeremiah', 24, 3, '&nbsp;نو بيا مالِک خُدائ ما ته وفرمائيل، ”يرمياه تا ته څۀ ښکارى؟“ ما ورته په جواب کښې ووئيل، ”اينځر. ښۀ اينځر ډېر ښۀ دى خو خراب اينځر ډېر خراب دى، دومره خراب دى چې د خوړلو قابل هم نۀ دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18415, 'Jeremiah 24:4', 'Jeremiah', 24, 4, '&nbsp;نو بيا د مالِک خُدائ کلام په ما نازل شو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18416, 'Jeremiah 24:5', 'Jeremiah', 24, 5, '&nbsp;”مالِک خُدائ، د بنى اِسرائيلو خُدائ پاک داسې فرمائى چې، دا ښۀ اينځر د يهوداه د هغه خلقو په شان دى چې ما د بابل مُلک ته د دې ځائ نه جلاوطن کړى دى او زۀ هغوئ ته هم دغه شان ښۀ ګورم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18417, 'Jeremiah 24:6', 'Jeremiah', 24, 6, '&nbsp;زۀ به هغوئ ته په ښۀ سترګه ګورم، او زۀ به هغوئ دې مُلک ته واپس راولم. زۀ به هغوئ آباد کړم او زۀ به هغوئ ونۀ غورزوم، زۀ به هغوئ وکرم او د بېخ نه به يې نۀ راوباسم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18418, 'Jeremiah 24:7', 'Jeremiah', 24, 7, '&nbsp;زۀ به هغوئ له دا خواهش ورکړم چې هغوئ ما وپېژنى چې زۀ مالِک خُدائ يم. هغوئ به زما مخلوق وى، او زۀ به د هغوئ خُدائ پاک يم، ځکه چې هغوئ به په پوره زړۀ سره ما ته رجوع وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18419, 'Jeremiah 24:8', 'Jeremiah', 24, 8, '&nbsp;مالِک خُدائ وفرمائيل، هغه خراب اينځر چې دومره ډېر خراب دى چې د خوړلو قابل هم نۀ دى، نو دغه شان به زۀ د صدقياه د يهوداه بادشاه، او د هغۀ د آفسرانو سره څوک چې د يروشلم نه ژوندى پاتې شوى دى کۀ هغه دلته اوسيږى او يا کۀ په مِصر کښې دى دغه شان سلوک وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18420, 'Jeremiah 24:9', 'Jeremiah', 24, 9, '&nbsp;زۀ به هغوئ په زمکه د هر يو مُلک دپاره د دهشت مثال او د افت زده ګانو نمونه وګرځوم. زۀ چې هغوئ چرته هم خوارۀ کړم نو هغوئ به د عبرت يو مثال جوړ شى او خلق به د هغوئ نوم د بې‌عزتۍ دپاره استعمالوى او د هغوئ بې‌عزتى به کوى او لعنت به پرې وائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18421, 'Jeremiah 24:10', 'Jeremiah', 24, 10, '&nbsp;زۀ به په هغوئ جنګ راولم، لوږه او وبا به پرې راولم، تر هغې پورې چې هغوئ به په هغه مُلک کښې ختم کړم کوم چې ما دوئ او د دوئ پلار نيکۀ له ورکړے وو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18422, 'Jeremiah 25:1', 'Jeremiah', 25, 1, '&nbsp;يرمياه ته د يهوداه بادشاه د يوسياه د زوئ يهويقيم د بادشاهۍ په څلورم کال، د يهوداه د ټولو خلقو په حقله د مالِک خُدائ د طرف نه پېغام ورکړے شو. په هم دغه کال باندې نبوکدنضر د بابل په تخت کښېناستو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18423, 'Jeremiah 25:2', 'Jeremiah', 25, 2, '&nbsp;نو بيا يرمياه نبى د يروشلم ټولو اوسېدونکو او د يهوداه ټول قوم ته بيان وکړو او ورته يې وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18424, 'Jeremiah 25:3', 'Jeremiah', 25, 3, '&nbsp;”د يهوداه بادشاه د امون د زوئ يوسياه د بادشاهۍ د ديارلسم کال نه واخله، تر اوسه پورې مالِک خُدائ د درويشتو کالو دپاره ما ته پېغام راکړو او ما هغه تاسو ته څو ځله در رسولے دے، خو تاسو ما ته غوږ ونۀ نيولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18425, 'Jeremiah 25:4', 'Jeremiah', 25, 4, '&nbsp;سره د دې چې مالِک خُدائ بيا بيا خپل خِدمتګاران پېغمبران رالېږلى دى، تاسو هغوئ ته نۀ غوږ نيولو او نۀ مو هغوئ ته توجو ورکوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18426, 'Jeremiah 25:5', 'Jeremiah', 25, 5, '&nbsp;هغوئ به تاسو ته فرمائيل چې، تاسو هر يو خپلې خرابې طريقې او هغه بد کارونه پرېږدئ کوم چې تاسو کوئ، نو بيا تاسو په هغه مُلک کښې تر تله پورې اوسېدلے شئ کوم چې ما تاسو او ستاسو پلار نيکۀ له ورکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18427, 'Jeremiah 25:6', 'Jeremiah', 25, 6, '&nbsp;هغوئ به تاسو ته فرمائيل چې د نورو معبودانو عبادت او خِدمت مۀ کوئ، تاسو چې په خپلو لاسونو کوم بُتان جوړ کړى دى هغوئ ته په عبادت کولو زما قهر مۀ راپاروئ. نو بيا به زۀ تاسو ته نقصان نۀ درکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18428, 'Jeremiah 25:7', 'Jeremiah', 25, 7, '&nbsp;مالِک خُدائ وفرمائيل چې، خو تاسو ما ته غوږ ونۀ نيولو، او تاسو چې څۀ جوړ کړى وُو د هغې په وجه تاسو زۀ په قهر او غصه کړم، او تاسو په خپله خپل ځان ته نقصان ورسولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18429, 'Jeremiah 25:8', 'Jeremiah', 25, 8, '&nbsp;نو په دې وجه مالِک خُدائ ربُ الافواج داسې فرمائى چې، ځکه چې تاسو زما پېغام ته غوږ ونۀ نيولو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18430, 'Jeremiah 25:9', 'Jeremiah', 25, 9, '&nbsp;زۀ به د شمال ټول خلق او خپل خدمتګار د بابل بادشاه نبوکدنضر د دې مُلک او په دې کښې د اوسېدونکو خلقو او د خواوشا ټولو قومونو په خلاف د جنګ دپاره راولېږم. زۀ به هغوئ بلکل تباه کړم او هغوئ به د خلقو دپاره د يرې دهشت، ټوقو، او مسخرو يو مثال وګرځوم، او په ابدى کنډرو به يې بدل کړم. مالِک خُدائ دا فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18431, 'Jeremiah 25:10', 'Jeremiah', 25, 10, '&nbsp;زۀ به د هغوئ د خندا او د خوشحالۍ چغې د دې ځائ نه خاموش کړم او زۀ به د هغوئ د وادۀ د ناوې او د زلمى د خوشحالۍ آوازونه خاموش کړم. د هغوئ د مېچونو آوازونه به خاموش کړم او د هغوئ ډيوې به مړې کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18432, 'Jeremiah 25:11', 'Jeremiah', 25, 11, '&nbsp;دا ټول مُلک به په شاړو او خرابو باندې بدل شى، او دا قومونه به د اويا کالونو دپاره د بابل د بادشاه خِدمت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18433, 'Jeremiah 25:12', 'Jeremiah', 25, 12, '&nbsp;خو چې کله اويا کالونه پوره شى، نو بيا به زۀ د بابل بادشاه او د هغۀ قوم، او د هغۀ مُلک له سزا ورکړم، د هغوئ د هغه ګناهونو په وجه کوم چې هغوئ کړى دى، مالِک خُدائ دا فرمائى، او د تل دپاره به د بابل مُلک په دشته او خرابه بدل کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18434, 'Jeremiah 25:13', 'Jeremiah', 25, 13, '&nbsp;زۀ به په دې مُلک هغه ټول افتونه راولم کوم چې ما د دۀ خلاف بيان کړى دى، او په دې کِتاب کښې ليکلے شوى دى او کوم چې د يرمياه نبى په ذريعه د ټولو قومونو خلاف پېشګوئې شوې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18435, 'Jeremiah 25:14', 'Jeremiah', 25, 14, '&nbsp;نور ډېر قومونه او غټ بادشاهان به هغوئ غلامان جوړ کړى، او زۀ به هغوئ ته هم هغه شان سزا ورکړم کومه سزا چې هغوئ نورو ته ورکړې وه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18436, 'Jeremiah 25:15', 'Jeremiah', 25, 15, '&nbsp;مالِک خُدائ چې د بنى اِسرائيلو خُدائ پاک دے ما ته يې وفرمائيل، ”زما د لاس نه دا پيالۍ واخله چې زما د غضب د شرابو نه ډکه ده او ټولو قومونو ته چې زۀ تا استوم په هغوئ يې وڅښوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18437, 'Jeremiah 25:16', 'Jeremiah', 25, 16, '&nbsp;کله چې هغوئ دا وڅښى، نو هغوئ ټول به زنګيږى او تيندکونه به خورى او کوم جنګ چې زۀ په دوئ باندې راولم د هغې په وجه به ليونى شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18438, 'Jeremiah 25:17', 'Jeremiah', 25, 17, '&nbsp;نو بيا ما د مالِک خُدائ د لاس نه پيالۍ واخستله او په هغه ټولو قومونو مې وڅښله چې زۀ چا ته هغۀ ورلېږلے وم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18439, 'Jeremiah 25:18', 'Jeremiah', 25, 18, '&nbsp;زۀ يروشلم او د يهوداه ټولو ښارونو او د هغوئ بادشاهانو او مشرانو له لاړم او هغوئ ټولو د غضب د پيالۍ نه وڅښل. د هغه وخت نه تر اوسه پورې، دا مُلک تباه شو، او د هغوئ دپاره د يرې او دهشت، ټوقو مسخرو شو او خلقو د هغوئ په نومونو لعنت وئيلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18440, 'Jeremiah 25:19', 'Jeremiah', 25, 19, '&nbsp;ما دا پيالۍ فِرعون د مِصر بادشاه او د هغۀ نوکرانو او آفسرانو له او ټولو مِصريانو له ورکړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18441, 'Jeremiah 25:20', 'Jeremiah', 25, 20, '&nbsp;او نورو ټولو هغه پردو خلقو ته څوک چې په دې مُلک کښې اوسېدل، او د عُوض ټولو بادشاهانو ته، د فلستيه د ټولو ښارونو بادشاهانو ته لکه اسقلون، غزه، عقرون، او کوم خلق چې په اشدود کښې پاتې وُو ورکړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18442, 'Jeremiah 25:21', 'Jeremiah', 25, 21, '&nbsp;د ادوم، موآب او عمون قومونه ته،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18443, 'Jeremiah 25:22', 'Jeremiah', 25, 22, '&nbsp;د صور او صيدا ټولو بادشاهانو ته، او د سمندر د ساحلى علاقو بادشاهانو ته،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18444, 'Jeremiah 25:23', 'Jeremiah', 25, 23, '&nbsp;د ددان، تيما او بُوز ښارونو او هغه ټولو خلقو ته څوک چې لرې اوسېدل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18445, 'Jeremiah 25:24', 'Jeremiah', 25, 24, '&nbsp;د عربو ټولو بادشاهانو ته او د ټولو هغه اجنبيانو بادشاهانو ته چې هلته په ريګستان کښې اوسېدل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18446, 'Jeremiah 25:25', 'Jeremiah', 25, 25, '&nbsp;د زِمرى، عيلام او د مادى ټولو بادشاهانو ته،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18447, 'Jeremiah 25:26', 'Jeremiah', 25, 26, '&nbsp;او ما د شمال ټولو نزدې لرې بادشاهانو ته، او پرله پسې د زمکې په مخ ټولو بادشاهتونو ته ورکړه. او د دې هر څۀ نه وروستو د بابل بادشاه به يې هم وڅښى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18448, 'Jeremiah 25:27', 'Jeremiah', 25, 27, '&nbsp;بيا مالِک خُدائ ما ته وفرمائيل، ”اوس هغوئ ته ووايه چې، مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى، تاسو وڅښئ چې نشه شئ او اولټۍ وکړئ، او چې راوغورزېږئ چې بيا هيڅکله راپورته نۀ شئ ځکه چې زۀ به په تاسو جنګ راولم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18449, 'Jeremiah 25:28', 'Jeremiah', 25, 28, '&nbsp;خو کۀ هغوئ ستا د لاس د پيالۍ اخستلو او څښلو نه اِنکار وکړى، هغوئ ته ووايه، مالِک خُدائ ربُ الافواج فرمائى چې، دا پيالۍ به ضرور څښئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18450, 'Jeremiah 25:29', 'Jeremiah', 25, 29, '&nbsp;ګورئ چې ما د تباهۍ کار په يروشلم کښې شروع کړلو کوم ښار چې زما په نوم ياديږى. نو ولې تاسو به د سزا نه خلاص شئ څۀ؟ تاسو به بې‌سزا پاتې نۀ شئ، ځکه چې زۀ په ټوله زمکه کښې او د هغوئ په ټولو اوسېدونکو باندې جنګ راولم، مالِک خُدائ ربُ الافواج دا فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18451, 'Jeremiah 25:30', 'Jeremiah', 25, 30, '&nbsp;نو اوس دا ټولې خبرې د هغوئ خلاف بيان کړه او هغوئ ته ووايه چې، مالِک خُدائ به د آسمان د اوچتو او مقدسو ځايونو نه لکه د ازمرى په شان وغړمبيږى او هغه به د خپل وطن خلاف زورَور آوازونه وکړى. او هغه به داسې په تېزه آوازونه وکړى لکه څنګه چې د انګورو نچوړونکى په هغه وخت کښې شور کوى. او هغه به د هغوئ ټولو خلاف په زوره چغې ووهى څوک چې په دُنيا کښې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18452, 'Jeremiah 25:31', 'Jeremiah', 25, 31, '&nbsp;او د هغۀ د عدالت آواز به د دُنيا د يو سر نه تر بل سره پورې ورسيږى. ځکه چې مالِک خُدائ د قومونو خِلاف عدالت کوى. او هغه به د ټولو انسانانو فېصله واوروى او بدکاران به جنګونو ته حواله کړى. مالِک خُدائ دا فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18453, 'Jeremiah 25:32', 'Jeremiah', 25, 32, '&nbsp;ربُ الافواج داسې فرمائى چې، وګورئ، افت د يو مُلک نه بل مُلک ته پيوسته خوريږى او يو لوئ طوفان د دُنيا د بل سر نه راروان دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18454, 'Jeremiah 25:33', 'Jeremiah', 25, 33, '&nbsp;په هغه ورځ به چې کوم خلق مالِک خُدائ وژلى وى د هغوئ لاشونه به هر چرته د دُنيا د يو سر نه تر بل سره پورې پراتۀ وى. په هغوئ باندې به نۀ څوک ماتم کوى او نۀ به يې څوک رايوځائ کولے شى او نۀ به ښخولے شى خو په زمکه به لکه د ډيران د ډيرى په شان پراتۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18455, 'Jeremiah 25:34', 'Jeremiah', 25, 34, '&nbsp;اے د قوم شپونکو تاسو په خپل ځان باندې ژړا او ماتم وکړئ، او اے د قومونو مشرانو تاسو په خاورو ايرو کښې ورغړېږئ. ځکه ستاسو د حلالېدلو او خورېدلو وخت رارسېدلے دے. تاسو به د خټو د نازک لوښى په شان راوغورزېږئ او ټوکړې ټوکړې به شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18456, 'Jeremiah 25:35', 'Jeremiah', 25, 35, '&nbsp;د شپونکو سره به د تېښتې دپاره يو ځائ هم نۀ وى، او د قوم د مشرانو سره به د منډې دپاره يو ځائ هم نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18457, 'Jeremiah 25:36', 'Jeremiah', 25, 36, '&nbsp;د شپونکو ژړا انګولا واورئ، او د قوم د مشرانو ژړا او فرياد واورئ، ځکه چې مالِک خُدائ د هغوئ مُلک تباه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18458, 'Jeremiah 25:37', 'Jeremiah', 25, 37, '&nbsp;د مالِک خُدائ د يروونکى قهر په وجه به د آرام ځايونه خراب شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18459, 'Jeremiah 25:38', 'Jeremiah', 25, 38, '&nbsp;مالِک خُدائ لکه د يو طاقتور ازمرى په شان کله چې د خپل غار نه راوځى او په خلقو حمله وکړى نو دغه شان به د ظالم تيره تُوره او د مالِک خُدائ سخت قهر به د هغوئ مُلک تباه کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18460, 'Jeremiah 26:1', 'Jeremiah', 26, 1, '&nbsp;دلته يرمياه ته د مالِک خُدائ پېغام د يهويقيم د يوسياه د زوئ د يهوداه بادشاه د حکومت په وړومبنى سر کښې ورکړے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18461, 'Jeremiah 26:2', 'Jeremiah', 26, 2, '&nbsp;مالِک خُدائ هغۀ ته داسې وفرمائيل چې، ”لاړ شه او د مالِک خُدائ د کور په دربار کښې ودرېږه، او هغه خلقو ته اعلان وکړه څوک چې د يهوداه د خوا او شا ښارونو نه د عبادت دپاره راغلى دى. هغوئ ته زما کلام پوره پوره واوروه او يو لفظ هم ترې نه کم نۀ کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18462, 'Jeremiah 26:3', 'Jeremiah', 26, 3, '&nbsp;کېدے شى چې هغوئ تا ته غوږ ونيسى او هر يو د خپلو بدو لارو نه راواوړى. کومه منصوبه چې ما د هغوئ خلاف جوړه کړې وه، نو بيا به زۀ خپل سوچ بدل کړم او هغه افت به پرې نۀ راولم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18463, 'Jeremiah 26:4', 'Jeremiah', 26, 4, '&nbsp;هغوئ ته ووايه، مالِک خُدائ فرمائى، کۀ چرې تاسو ما ته غوږ ونۀ نيسئ او کوم شريعت چې ما تاسو ته پېش کړے دے د هغې پيروى ونۀ کړئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18464, 'Jeremiah 26:5', 'Jeremiah', 26, 5, '&nbsp;او کۀ چرې تاسو زما د خِدمت کوونکو پېغمبرانو کلام ته غوږ ونۀ نيسئ کوم چې ما تاسو ته بار بار درلېږلى دى خو تاسو هغوئ ته غوږ ونۀ نيولو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18465, 'Jeremiah 26:6', 'Jeremiah', 26, 6, '&nbsp;نو زۀ به د دې کور سره هم هغه شان کار وکړم لکه څنګه مې چې د سيلا سره کړے وو، او د زمکې په مخ به د دُنيا ټول قومونه د دې ښار نوم په لعنت کولو سره اخلى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18466, 'Jeremiah 26:7', 'Jeremiah', 26, 7, '&nbsp;کله چې يرمياه د مالِک خُدائ په کور کښې دا کلام واورولو نو اِمامانو، پېغمبرانو او ټولو خلقو د هغۀ کلام واورېدو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18467, 'Jeremiah 26:8', 'Jeremiah', 26, 8, '&nbsp;نو چې څنګه يرمياه هغه کلام خلقو ته اورول ختم کړو کوم چې ورته مالِک خُدائ حکم کړے وو چې دې خلقو ته يې واوروى نو سمدستى اِمامانو، نبيانو او ټولو خلقو هغه ونيولو او چغې يې کړې، ”دا ضرورى ده چې تۀ د دې په وجه مړ شې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18468, 'Jeremiah 26:9', 'Jeremiah', 26, 9, '&nbsp;تۀ ولې د مالِک خُدائ په کور کښې د هغۀ په نوم پېغام ورکوې چې دا کور به لکه د سيلا په شان شى او دا ښار به په صحرا او کنډرو بدل شى؟“ نو د مالِک خُدائ په کور کښې ټول خلق د يرمياه نه راتاو شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18469, 'Jeremiah 26:10', 'Jeremiah', 26, 10, '&nbsp;کله چې د يهوداه آفسرانو د دې خبرو په حقله واورېدل، هغوئ د شاهى محل نه د مالِک خُدائ د کور طرف ته لاړل او هلته د نوې دروازې په نوم دروازه کښې په داخلېدو سره په خپلو ځايونو باندې کښېناستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18470, 'Jeremiah 26:11', 'Jeremiah', 26, 11, '&nbsp;نو بيا اِمامانو او پېغمبرانو، ټولو آفسرانو او نورو خلقو ته وفرمائيل چې، ”دې سړى ته دې د مرګ سزا ورکړے شى ځکه چې هغۀ د دې ښار خِلاف پېشګوئې وکړه او تاسو په خپلو غوږُونو واورېده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18471, 'Jeremiah 26:12', 'Jeremiah', 26, 12, '&nbsp;نو بيا يرمياه ټولو آفسرانو او ټولو خلقو ته وفرمائيل، ”زۀ مالِک خُدائ رالېږلے يم چې د دې کور او د دې ښار خِلاف هغه ټولې پېشګويانې وکړم کومې چې تاسو واورېدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18472, 'Jeremiah 26:13', 'Jeremiah', 26, 13, '&nbsp;تاسو اوس د خپلو طريقو او اعمالو اصلاح وکړئ او د مالِک خُدائ ستاسو د خُدائ پاک تابعدارى وکړئ. نو بيا به مالِک خُدائ خپل سوچ بدل کړى او د کوم افت د نازلېدو منصوبه يې چې جوړه کړې ده هغه به نۀ نازلوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18473, 'Jeremiah 26:14', 'Jeremiah', 26, 14, '&nbsp;ترڅو پورې چې زما خبره ده، زۀ خو ستاسو په قبضه کښې يم، څۀ چې تاسو ته ښۀ او صحيح ښکارى هم هغه ما سره وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18474, 'Jeremiah 26:15', 'Jeremiah', 26, 15, '&nbsp;خو تاسو په دې يقين وساتئ، کۀ چرې تاسو ما مړ کړئ، نو تاسو او د دې ښار خلق څوک چې په کښې اوسيږى د يو بې‌ګناه کس خون به په خپله غاړه واخلئ ځکه چې په حقيقت کښې زۀ مالِک خُدائ تاسو ته رالېږلے يم، چې دا ټولې خبرې ستاسو غوږونو ته درورسوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18475, 'Jeremiah 26:16', 'Jeremiah', 26, 16, '&nbsp;نو آفسرانو او خلقو چې دا واورېدل، نو اِمامانو او پېغمبرانو ته يې ووئيل، ”دې سړى ته دې د مرګ سزا ورنۀ کړے شى، ځکه چې هغۀ مونږ ته د مالِک خُدائ زمونږ د خُدائ پاک په نوم خبرې وکړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18476, 'Jeremiah 26:17', 'Jeremiah', 26, 17, '&nbsp;نو بيا د قوم يو څو مشران راپاڅېدل او ټولو حاضرو خلقو ته يې ووئيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18477, 'Jeremiah 26:18', 'Jeremiah', 26, 18, '&nbsp;”د مورشيت ميکاه نبى چې د حزقياه د بادشاهت په ورځو کښې د يهوداه بادشاه وو، پېشګوئې وکړه. هغۀ د يهوداه ټولو خلقو ته وفرمائيل، دا هغه څۀ دى چې مالِک خُدائ ربُ الافواج يې فرمائى، صيون به لکه د پټې په شان په يوې واړولے‎ شى، د يروشلم نه به د خاورو ډېرے جوړ شى، او په اوچتو غونډو چرته چې د خُدائ کور دے په هغې کښې به جاړې بوټى راشنۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18478, 'Jeremiah 26:19', 'Jeremiah', 26, 19, '&nbsp;ولې حزقياه چې د يهوداه بادشاه وو هغه په مرګ محکوم کړو څۀ؟ آيا حزقياه د مالِک خُدائ نه ونۀ يرېدو چې د هغۀ رحم ولټوى؟ آيا مالِک خُدائ خپله فېصله بدله نۀ کړه د کوم افت د رانازلېدو چې هغۀ د دوئ خلاف منصوبه جوړه کړې وه؟ مونږ په خپله په خپل ځان د سخت افت راوستو په حالت کښې يُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18479, 'Jeremiah 26:20', 'Jeremiah', 26, 20, '&nbsp;په هغه ورځو کښې يو بل نبى د اورِياه په نوم چې د قِريَت‌يعريم اوسېدونکے وو او د سمعياه زوئ وو د يرمياه نبى په شان د مالِک خُدائ په نوم نبوت کولو. هغۀ هم د دې ښار او د دې خلقو خلاف لکه څنګه چې يرمياه خبرې کړې وې يو شان خبرې وکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18480, 'Jeremiah 26:21', 'Jeremiah', 26, 21, '&nbsp;کله چې يهويقيم بادشاه، او د هغۀ ټولو فوجيانو او آفسرانو د اورِياه خبرې واورېدلې، نو بادشاه د هغۀ د قتلولو کوشش وکړو. خو کله چې اورِياه واورېدل نو د يرې نه مِصر ته وتښتېدلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18481, 'Jeremiah 26:22', 'Jeremiah', 26, 22, '&nbsp;نو بيا يهويقيم بادشاه الناتن د عکبور زوئ مِصر ته سره د نورو کسانو ولېږلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18482, 'Jeremiah 26:23', 'Jeremiah', 26, 23, '&nbsp;نو هغوئ اورِياه په مِصر کښې ونيولو او يهويقيم بادشاه له يې راوستلو، او هغه يې په تُوره قتل کړو او د هغۀ لاش يې د عامو خلقو په قبرستان کښې ښخ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18483, 'Jeremiah 26:24', 'Jeremiah', 26, 24, '&nbsp;خو اخيقام د سافن زوئ د يرمياه مدد کولو، نو ځکه هغه د مرګ دپاره خلقو ته حواله نۀ کړے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18484, 'Jeremiah 27:1', 'Jeremiah', 27, 1, '&nbsp;د صدقياه د يوسياه د زوئ د يهوداه د بادشاهۍ په تازه ورځو کښې دا پېغام يرمياه ته د مالِک خُدائ له طرفه ورکړے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18485, 'Jeremiah 27:2', 'Jeremiah', 27, 2, '&nbsp;مالِک خُدائ ما ته وفرمائيل چې، ”د خپل ځان دپاره جغ جوړ کړه او د څرمنې په تسمو سره يې په خپله غاړه کښې واچوه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18486, 'Jeremiah 27:3', 'Jeremiah', 27, 3, '&nbsp;بيا مالِک خُدائ ما ته وفرمائيل چې، ”د ادوم، موآب، عمون، صور او د صيدا بادشاهانو ته د هغوئ د هغه سفيرانو په ذريعه پېغام ورواستوه څوک چې يروشلم ته د يهوداه د بادشاه صدقياه ليدلو له راغلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18487, 'Jeremiah 27:4', 'Jeremiah', 27, 4, '&nbsp;هغوئ له دا پېغام د هغوئ د مالِکانو دپاره ورکړه چې دا هغه څۀ دى چې ربُ الافواج د بنى اِسرائيلو مالِک خُدائ يې فرمائى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18488, 'Jeremiah 27:5', 'Jeremiah', 27, 5, '&nbsp;ما په خپل لوئ طاقت او زورَور لاس سره زمکه او په کښې ټول انسانان او ځناور پېدا کړل، او هر چا ته چې زما خوښه وى نو بيا دا هغوئ له ورکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18489, 'Jeremiah 27:6', 'Jeremiah', 27, 6, '&nbsp;خو زۀ به اوس ستاسو ټول مُلکونه خپل خِدمت کوونکى نبوکدنضر د بابل بادشاه ته حواله کړم، تر دې چې زۀ به ځنګلى ځناور هم د دۀ تابعدار کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18490, 'Jeremiah 27:7', 'Jeremiah', 27, 7, '&nbsp;ټول قومونه به د هغۀ خِدمت وکړى، او د هغۀ د زوئ او د نمسى به تر هغې پورې خِدمت کوى ترڅو چې د هغۀ د مُلک د ختمېدو دپاره مقرر شوے وخت نۀ وى راغلے. نو بيا به نور ډېر قومونه او لوئ بادشاهان راشى او بابليان به خپل غلامان جوړ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18491, 'Jeremiah 27:8', 'Jeremiah', 27, 8, '&nbsp;مالِک خُدائ داسې فرمائى چې، کۀ چرې يو قوم يا بادشاهت د نبوکدنضر يعنې د بابل د بادشاه د خِدمت نه اِنکار وکړى او يا خپل څټ د هغۀ د جغ لاندې نۀ کړى، نو زۀ به بيا په هغه قوم جنګ، قحط او وبا را نازله کړم، ترڅو چې بابليانو هغه قبضه کړے نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18492, 'Jeremiah 27:9', 'Jeremiah', 27, 9, '&nbsp;نو بيا خپلو دروغژنو نبيانو، فالګرو، د خوب تعبير کوونکو، خپل قسمت معلومونکو او جادوګرو ته غوږ مۀ نيسئ، څوک چې تاسو ته وائى چې تاسو به د بابل د بادشاه خِدمت نۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18493, 'Jeremiah 27:10', 'Jeremiah', 27, 10, '&nbsp;هغوئ تاسو ته د دروغو نبوت کوى او په دې خبرو به تاسو د خپل مُلک نه لرې وشړلے شئ، زۀ به تاسو خوارۀ وارۀ کړم او تاسو به تباه شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18494, 'Jeremiah 27:11', 'Jeremiah', 27, 11, '&nbsp;خو کۀ کوم يو قوم هم خپل څټ د بابل بادشاه د جغ لاندې ښکته کړى او د هغۀ خِدمت وکړى، نو زۀ به دا قوم په خپله زمکه باندې پرېږدم چې هغه وکَرى او هلته اوسيږى.“ دا د مالِک خُدائ وينا ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18495, 'Jeremiah 27:12', 'Jeremiah', 27, 12, '&nbsp;ما هم دا پېغام د يهوداه بادشاه صدقياه ته ورکړو. ما ورته ووئيل، ”خپل څټونه د بابل بادشاه جغ ته ښکته کړئ، د هغۀ او د هغۀ د خلقو خِدمت وکړئ، نو تاسو به ژوندى پاتې شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18496, 'Jeremiah 27:13', 'Jeremiah', 27, 13, '&nbsp;نو بيا ولې تۀ او ستا عوام دې په هغه جنګ، قحط يا وبا مړۀ شى په کومو چې مالِک خُدائ هر هغه قوم يروى څوک چې د بابل د بادشاه د خِدمت نه اِنکار کوى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18497, 'Jeremiah 27:14', 'Jeremiah', 27, 14, '&nbsp;د دروغژنو نبيانو خبرو ته غوږ مۀ نيسئ څوک چې تاسو ته وائى چې د بابل د بادشاه خِدمت به نۀ کوئ، ځکه چې هغوئ تاسو ته دروغ وائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18498, 'Jeremiah 27:15', 'Jeremiah', 27, 15, '&nbsp;مالِک خُدائ په خپله فرمائيلى دى چې، هغوئ ما نۀ دى درلېږلى. هغوئ زما په نوم د دروغو نبوت کوى. نو ځکه زۀ به تاسو د خپل مُلک نه وشړم، نو تاسو او هغه نبيان دواړه به هلاک شئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18499, 'Jeremiah 27:16', 'Jeremiah', 27, 16, '&nbsp;نو بيا ما اِمامانو ته ووئيل چې، ”دا هغه څۀ دى چې مالِک خُدائ فرمائيلى دى، هغه نبيانو ته غوږ مۀ نيسئ چې څوک داسې وائى چې د خُدائ پاک د کور مقدس څيزونه به ډېر زر د بابل نه راواپس شى. هغوئ تاسو ته د دروغو پېشګويانې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18500, 'Jeremiah 27:17', 'Jeremiah', 27, 17, '&nbsp;هغوئ ته غوږ مۀ نيسئ، د بابل د بادشاه خِدمت کوئ، نو تاسو به ژوندى پاتې شئ. نو بيا دې ولې دا ښار تباه او په کنډرو بدل شى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');